import{_ as r,l,o as e,c as o,v as t,p as s,x as i,d as n,i as u,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"auditd","description":"","frontmatter":{"title":"auditd","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-audit.md","filePath":"cs/kernel-audit.md","lastUpdated":1789023840000}'),p={name:"cs/kernel-audit.md"};function h(f,a,m,_,k,x){const d=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="auditd" tabindex="-1">auditd <a class="header-anchor" href="#auditd" aria-label="Permalink to &quot;auditd&quot;">​</a></h1><div class="epigraph"><p>audit 子系统在钩子上生成记录：谁、何时、哪个系统调用、成功与否；auditd 在用户态写盘并轮转。</p><footer>—— 据 Linux audit 文档；[LSM](/cs/lsm-selinux) 拒绝路径；McKusick 对安全日志的背景</footer></div><p><a href="/cs/lsm-selinux">SELinux</a>/<a href="/cs/apparmor">AppArmor</a> 的拒绝需要 <strong>可问责</strong>。缺口是内核 audit + auditd，不是 syslog 的全部。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规则：监视 <code>open</code> 某文件、cap 使用、exec。内核 <code>kauditd</code> 把记录送给用户 netlink。缺口：规则过多则 CPU 与丢事件；与 <a href="/cs/inotify">inotify</a> 不同——audit 是安全审计不是 IDE 热重载。本课不把每条 syscall 字段当作业。</p><p><span class="marginnote">immutable 标志可锁规则直到重启。容器要小心宿主机审计范围。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>auditctl</code> 下规则 → 系统调用返回路径发包 → auditd 写 <code>/var/log/audit</code>。对照 [fsnotify]：一个给桌面，一个给合规。对照 <a href="/cs/netfilter-conntrack">netfilter</a> 日志：对象不同。对照 printk 后课：dmesg 不是审计。</p>',8)),(e(),s(c,null,{default:i(()=>[u(d,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22syscall%2FLSM%22%5D%20--%3E%20KRULE%5B%22audit%20%E8%A7%84%E5%88%99%22%5D%0A%20%20KRULE%20--%3E%20NL%5B%22netlink%22%5D%0A%20%20NL%20--%3E%20AD%5B%22auditd%20%E8%90%BD%E7%9B%98%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>audit 把内核决策变成不可轻易抵赖的序列（在磁盘与权限保护下）。它不阻止攻击，只留下痕迹。不要写成 SIEM 产品。与 <a href="/cs/fsync">fsync</a>：日志完整性依赖刷盘策略。</p><p>洪水：攻击者可用事件灌满，规则设计要有上限意识。</p><p>实现上：规则用 syscall 号和字段过滤，架构不同号不同。kauditd 拥塞会丢，不是可靠队列。immutable 后改规则要重启。 读法上只引用<a href="/cs/apparmor">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>auditd</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 arch 特定字段。不保证网络启动早期的 audit。下一课启动链：安全启动与签名。</p><p>版本字段会变，课序钉的是机制对象「auditd」，不是某一主线内核的结构体名。 后课默认：特权与 MAC 决策可被审计。固件验证内核签名，下一课安全启动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>audit 在内核生成事件，auditd 落盘。</li><li>与 inotify 目标不同；过量规则会丢。</li><li>安全启动是下一课。</li><li>出处：Linux audit；auditd；LSM。</li></ul>',11))])}const E=r(p,[["render",h]]);export{A as __pageData,E as default};
